public class HorizontalHistogramPainterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String pixel(java.awt.image.BufferedImage img, int x, int y) {
        if (img == null) {
            return "null-image";
        }
        return String.format("#%06X", img.getRGB(x, y) & 0xFFFFFF);
    }

    static java.awt.image.BufferedImage render(int[] values, int width, int height) {
        java.awt.image.BufferedImage img = new java.awt.image.BufferedImage(
                width, height, java.awt.image.BufferedImage.TYPE_INT_RGB);
        java.awt.Graphics2D g = img.createGraphics();
        try {
            HorizontalHistogramPainter.paint(g, values, width, height);
        } finally {
            g.dispose();
        }
        return img;
    }

    public static void main(String[] args) {
        try {
            java.awt.image.BufferedImage a = render(new int[] { 4, 8, 2, 6 }, 100, 80);
            java.awt.image.BufferedImage b = render(new int[] { 1 }, 60, 40);
            check("axis pixel (1,40)", "#000000", pixel(a, 1, 40));
            check("bar 0 body (20,10)", "#0000FF", pixel(a, 20, 10));
            check("white past the end of bar 0 (70,10)", "#FFFFFF", pixel(a, 70, 10));
            check("longest bar reaches the right (90,30)", "#0000FF", pixel(a, 90, 30));
            check("short bar 2 body (10,50)", "#0000FF", pixel(a, 10, 50));
            check("white past the end of bar 2 (40,50)", "#FFFFFF", pixel(a, 40, 50));
            check("gap between rows (20,20)", "#FFFFFF", pixel(a, 20, 20));
            check("single full-length bar (40,20)", "#0000FF", pixel(b, 40, 20));
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

