import java.awt.Color;
import java.awt.Graphics2D;

public class HorizontalHistogramPainter {

    static final int AXIS = 3;

    public static void paint(Graphics2D g, int[] values, int width, int height) {
        g.setColor(Color.WHITE);
        g.fillRect(0, 0, width, height);
        g.setColor(Color.BLACK);
        g.fillRect(0, 0, AXIS, height);

        int max = 0;
        for (int v : values) {
            max = Math.max(max, v);
        }
        if (max <= 0) {
            return;
        }

        int rowHeight = height / values.length;
        g.setColor(Color.BLUE);
        for (int i = 0; i < values.length; i++) {
            int barLength = values[i] * (width - AXIS) / max;
            g.fillRect(AXIS, i * rowHeight + 2, barLength, rowHeight - 4);
        }
    }
}
